using System;
using System.IO;
using UnityEngine;
using UnityEditor;
namespace LWS.TruckHockey.Editor {
public static class HockeyAudioAuthoring {
 public static AudioClip[] Create(){Directory.CreateDirectory("Assets/TruckHockey/Audio");var clips=new AudioClip[7];clips[0]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Click.wav");clips[1]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBilliards/Audio/Ball.wav");clips[2]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBilliards/Audio/Cushion.wav");clips[3]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBilliards/Audio/Strike.wav");string[] names={"Faceoff","GoalHorn","FinalWhistle"};for(int kind=0;kind<3;kind++){string path="Assets/TruckHockey/Audio/"+names[kind]+".wav";int rate=44100;float duration=kind==0?.18f:kind==1?.9f:.65f;int samples=(int)(duration*rate);if(!File.Exists(path))using(var w=new BinaryWriter(File.Create(path))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+samples*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(samples*2);for(int i=0;i<samples;i++){double t=(double)i/rate,hz=kind==0?880:kind==1?196:2100;double envelope=Math.Min(1,t*120)*Math.Min(1,(duration-t)*60)*(kind==0?Math.Exp(-t*12):1);double value=kind==1?.35*Math.Sin(2*Math.PI*hz*t)+.14*Math.Sin(2*Math.PI*hz*1.5*t)+.07*Math.Sin(2*Math.PI*hz*2*t):.42*Math.Sin(2*Math.PI*hz*t+Math.Sin(t*50)*.4);w.Write((short)(value*envelope*short.MaxValue));}}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(AudioImporter)AssetImporter.GetAtPath(path);var config=importer.defaultSampleSettings;config.loadType=AudioClipLoadType.DecompressOnLoad;config.compressionFormat=AudioCompressionFormat.PCM;importer.defaultSampleSettings=config;importer.forceToMono=true;importer.SaveAndReimport();clips[4+kind]=AssetDatabase.LoadAssetAtPath<AudioClip>(path);}return clips;}
}
}
